select ideas.put_opportunities($j$[{"opportunity_key": "isu_petasys_tpu_v8_mlb", "title": "구글 TPU v8 고다층화에 따른 이수페타시스 기판 매출 확대", "stars": 3, "idea": "대만 경제일보(10/23)는 구글 TPU v8 기판이 34~40층으로 두꺼워지고 소재가 바뀌어 기판 한 장의 값이 70~80% 오른다고 보도했다. 이수페타시스는 TPU용 고다층 기판의 주력 공급사로 알려져 있고(최대 고객 매출 비중 약 45%), 2분기 매출 3,799억 원·영업이익률 20%로 분기 최대를 냈으며 4분기부터 평균 15% 안팎의 판가 인상을 협의 중이다. 시장은 대만 금상전(Gold Circuit)의 v8 진입(점유율 15~20% 전망)을 매출 감소로 읽어 주가를 고점 대비 약 40% 낮춰 놓았다. 가장 크게 틀릴 수 있는 지점은 대만 업체의 몫이 예상보다 커지는 것이다.", "interpretation": "공급사가 늘어 점유율은 내려가도, 기판 한 장의 값과 물량이 함께 늘어 TPU향 매출 금액은 커진다. 고다층·다중적층 기판은 수율이 경쟁력이라 새 공급사가 짧은 기간에 큰 몫을 가져가기 어렵다. 다만 시가총액 약 7조 원으로 성장이 상당 부분 가격에 들어 있어, 매출이 두 배 가까이 늘어야 지금 가격이 설명된다.", "companies": [{"company": "company:isu_petasys", "name": "이수페타시스", "ticker": "007660", "exchange": "KRX", "role": "primary"}, {"company": "company:gold_circuit", "name": "금상전(Gold Circuit, 대만)", "ticker": "2368", "exchange": "TWSE", "role": "related"}], "evidence": [{"title": "金像電 구글 TPU v8 공급망 진입 — v8 기판 34~40층, 장당 가치 70~80% 상승", "url": "https://money.udn.com/money/story/5607/9833568", "date": "2026-10-23", "publisher": "經濟日報"}, {"title": "이수페타시스 2분기 최대 실적 — 다중적층 비중 23%, 판가 15% 안팎 인상 협의", "url": "https://www.tokenpost.kr/news/market/401739", "date": "2026-09-02", "publisher": "토큰포스트"}, {"title": "키움증권: 이수페타시스 점유율·판가 우려 해소", "url": "https://www.etoday.co.kr/news/view/2550562", "date": "2026-01-29", "publisher": "이투데이"}], "nodes": ["product:google_tpu_system", "component:mlb_pcb"], "clue_refs": [{"title": "金像電 구글 TPU v8 공급망 진입 — v8 기판 34~40층, 장당 가치 70~80% 상승", "url": "https://money.udn.com/money/story/5607/9833568", "date": "2026-10-23", "publisher": "經濟日報"}], "status": "active", "model": "claude-opus-5-5 (세션, 수동 발굴)"}, {"opportunity_key": "tlb_socamm2_pcb", "title": "SOCAMM2 채택 확대에 따른 티엘비 모듈 기판 판가 상승", "stars": 3, "idea": "엔비디아 Vera CPU에 쓰이는 탈착식 저전력 메모리 모듈(SOCAMM2)은 CPU당 슬롯 수가 정해져 있어, 모듈당 메모리 용량이 줄어도 기판 수량은 줄지 않는다. 이 기판은 일반 서버 메모리 기판보다 약 3배 비싸다(IBK투자증권, 8/27). 티엘비는 올해 SOCAMM 매출 전망을 200억 원에서 500억, 700억 원으로 세 번 올렸고, 2분기 말 수주잔고는 1,318억 원이다. SOCAMM 비중은 올해 약 16%에서 내년 약 30%로 커질 전망인데, 주가는 메모리 경기 우려로 고점 대비 약 38% 낮다. 가장 크게 틀릴 수 있는 지점은 공급사 다섯 곳 사이의 점유율 경쟁(심텍이 50% 목표)과 유상증자에 따른 지분 희석이다.", "interpretation": "이 기판의 수요는 메모리 용량이 아니라 CPU 출하 대수와 슬롯 수를 따라가므로 메모리 가격·용량 경기와 다르게 움직인다. 판가가 일반 기판의 세 배라 비중이 커질수록 이익률도 함께 오른다. 다만 2025년에 같은 이야기로 이미 크게 오른 적이 있어, 새 숫자(수주잔고·SOCAMM 매출)가 나와야 다시 평가받는다.", "companies": [{"company": "company:tlb", "name": "티엘비", "ticker": "356860", "exchange": "KOSDAQ", "role": "primary"}, {"company": "company:simmtech", "name": "심텍", "ticker": "222800", "exchange": "KOSDAQ", "role": "related"}], "evidence": [{"title": "엔비디아 CPU 옆자리 정조준…티엘비 쏘캠 수혜 (IBK투자증권)", "url": "https://core.asiae.co.kr/article/2026082613254773558", "date": "2026-08-27", "publisher": "아시아경제"}, {"title": "티엘비, 소캠 공급 확대…3분기도 주문 증가세", "url": "https://etoday.co.kr/news/view/2614327", "date": "2026-08-25", "publisher": "이투데이"}, {"title": "심텍, SOCAMM용 기판 점유율 50% 목표 (iM증권)", "url": "https://www.fnnews.com/news/202606080748297422", "date": "2026-06-08", "publisher": "파이낸셜뉴스"}], "nodes": ["component:server_dram_lpdram", "component:memory_module_pcb"], "clue_refs": [{"title": "엔비디아 CPU 옆자리 정조준…티엘비 쏘캠 수혜 (IBK투자증권)", "url": "https://core.asiae.co.kr/article/2026082613254773558", "date": "2026-08-27", "publisher": "아시아경제"}], "status": "active", "model": "claude-opus-5-5 (세션, 수동 발굴)"}, {"opportunity_key": "ls_materials_aidc_uc", "title": "AI 데이터센터 연료전지 확산에 따른 LS머트리얼즈 울트라커패시터 수주 확대", "stars": 2, "idea": "LS머트리얼즈는 미국 수소연료전지 회사에 AI 데이터센터 전력 설비용 울트라커패시터 689억 원어치를 공급하는 계약을 맺었다(10/13, 지난해 매출의 44.85%, 2027년 4월부터 1년간). 연료전지가 따라가지 못하는 급격한 부하 변동을 커패시터가 흡수하는 용도로, 같은 용도로 비나텍도 대형 수주를 받았다. 회사는 연내 추가 계약이 나오면 누적 1억 달러를 넘는다고 밝혔다. 다만 계약이 유통사를 거치고 최종 고객 이름이 공개되지 않았으며, 수주 직후 오른 주가를 2주 만에 모두 반납했다. 가장 크게 틀릴 수 있는 지점은 지금 주가가 이미 큰 성장을 가정하고 있다는 점이다 — 울트라커패시터 사업은 아직 적자다.", "interpretation": "데이터센터가 전력망 대신 현장 연료전지로 전기를 만들기 시작하면서, 출력 변동을 받아 주는 커패시터라는 새 수요가 생겼다. 이 회사에는 매출의 절반에 가까운 계약이라 크지만, 공시로 이미 알려진 사실이고 이익 대비 주가로는 싸지 않다. 연내 추가 계약과 커패시터 사업의 흑자 전환이 보여야 큰 기회가 된다.", "companies": [{"company": "company:ls_materials", "name": "LS머트리얼즈", "ticker": "417200", "exchange": "KOSDAQ", "role": "primary"}, {"company": "company:vinatech", "name": "비나텍", "ticker": "126340", "exchange": "KOSDAQ", "role": "related"}], "evidence": [{"title": "LS머트리얼즈, 미국 수소연료전지사에 AI 데이터센터용 울트라커패시터 5,150만 달러 공급", "url": "https://core.asiae.co.kr/article/2026101310052724755", "date": "2026-10-13", "publisher": "아시아경제"}, {"title": "LS머트리얼즈 중형셀 가동률 67.5%…계약 상대방·계약기간·선급금", "url": "https://sateconomy.co.kr/news/view/1065575480990207", "date": "2026-10-27", "publisher": "토요경제"}, {"title": "LS머트리얼즈, 미국 기업과 공급 계약 연내 1억 달러 돌파 기대", "url": "https://ceoscoredaily.com/page/view/2026101416153725466", "date": "2026-10-14", "publisher": "CEO스코어데일리"}, {"title": "비나텍, 데이터센터용 슈퍼커패시터 대규모 공급 계약 잇따라", "url": "https://biz.sbs.co.kr/amp/article/20000341686", "date": "2026-10-23", "publisher": "SBS Biz"}], "nodes": ["component:fuel_cell", "component:supercapacitor"], "clue_refs": [{"title": "LS머트리얼즈, 미국 수소연료전지사에 AI 데이터센터용 울트라커패시터 5,150만 달러 공급", "url": "https://core.asiae.co.kr/article/2026101310052724755", "date": "2026-10-13", "publisher": "아시아경제"}], "status": "active", "model": "claude-opus-5-5 (세션, 수동 발굴)"}]$j$::jsonb);
